```go
package main

import (
    "fmt"
    "strconv"
)

func parse(text string) (int, error) {
    return strconv.Atoi(text)
}

func main() {
    var convert func(string) (int, error) = parse
    value, err := convert("42")
    fmt.Println(value, err)
}
```
The output is `42 <nil>`. Renaming `text` would not change the type, but changing the result from `(int, error)` to `int` would make the assignment fail.

```go
package main

import "fmt"

type Predicate func(int) bool

func filter(values []int, keep Predicate) []int {
    var result []int
    for _, value := range values {
        if keep(value) {
            result = append(result, value)
        }
    }
    return result
}

func main() {
    isEven := func(n int) bool { return n%2 == 0 }
    fmt.Println(filter([]int{1, 2, 3, 4}, isEven))
}
```
The output is `[2 4]`. Changing `isEven` to return an `int` produces a compile-time mismatch instead of a delayed runtime failure.

```go
package main

import (
    "context"
    "fmt"
)

func save(ctx context.Context, name string) error {
    fmt.Println("saved", name, ctx.Err())
    return nil
}

func run(name string, callback func(string) error) error {
    return callback(name)
}

func main() {
    ctx := context.Background()
    callback := func(name string) error { return save(ctx, name) }
    _ = run("report", callback)
}
```
The adapter has the exact `func(string) error` shape and makes the captured context explicit. The output is `saved report <nil>`.

