```go
package main

import "fmt"

type Hook func(string) error

func create(name string) (int, error) {
    return len(name), nil
}

func main() {
    var hook Hook = func(name string) error {
        id, err := create(name)
        fmt.Println("created id", id)
        return err
    }
    _ = hook("gopher")
}
```
The adapter explicitly handles the extra integer result. It prints `created id 6` and satisfies `Hook` at compile time.
